document.addEventListener("DOMContentLoaded", function () {
    var u = navigator.userAgent.toLowerCase(), b = document.body, i = /msie|trident/.test(u), c = /chrome/.test(u) && !/edge|edg|opr/.test(u), s = /safari/.test(u) && !/chrome|edge|edg|opr/.test(u), f = /firefox/.test(u), o = /opera|opr/.test(u); if (i) { b.classList.add("browserIE"); var m = u.match(/(msie\s|rv:)(\d+)/); if (m && m[2]) b.classList.add("browserIE" + m[2].substring(0, 1)) } if (c) { console.log("chrome found"); b.classList.add("browserChrome"); var ci = u.indexOf("chrome/"); if (ci !== -1) { var v = u.substring(ci + 7, ci + 8); b.classList.add("browserChrome" + v) } } if (s) { b.classList.add("browserSafari"); var si = u.indexOf("version/"); if (si !== -1) { var v = u.substring(si + 8, si + 9); b.classList.add("browserSafari" + v) } } if (f) { b.classList.add("browserFirefox"); var fi = u.indexOf("firefox/"); if (fi !== -1) { var v = u.substring(fi + 8, fi + 9); b.classList.add("browserFirefox" + v) } } else if (/mozilla/.test(u) && !i && !c && !s) b.classList.add("browserMozilla"); if (o) b.classList.add("browserOpera")
    console.log(u, i, f, c);
});